### Step-by-step Example

Below is a code snippet that demonstrates how to set up the MediaRecorder API to record both audio and video:

```javascript
// Function to start recording
async function startRecording() {
  try {
    // Request access to the user's audio and video
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: true,
      video: true
    });

    // Show video on the screen
    const videoElement = document.querySelector('video');
    videoElement.srcObject = stream;

    // Create a new MediaRecorder instance
    const mediaRecorder = new MediaRecorder(stream);

    // Array to store recorded chunks
    const chunks = [];

    // Event handler for when data is available
    mediaRecorder.ondataavailable = function(event) {
      if (event.data.size > 0) {
        chunks.push(event.data);
      }
    };

    // Event handler for when recording is stopped
    mediaRecorder.onstop = function() {
      const completeBlob = new Blob(chunks, { type: 'video/webm' });
      // Do something with the recorded media, e.g., save or upload
      const url = URL.createObjectURL(completeBlob);
      const downloadLink = document.createElement('a');
      downloadLink.href = url;
      downloadLink.download = 'recording.webm';
      downloadLink.click();
    };

