def <<factorial>>(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * <<factorial>>(n - 1)

number = 5  # You can change this value to test with other numbers
result = <<factorial>>(number)
print("The factorial of", number, "is", result)
```

